<?php
require_once __DIR__ . '/../includes/layout.php';

// Admins manage classes; teachers view their assignments.
$me=require_login(['admin','teacher']); $pdo=db(); $error='';
if ($me['role']==='admin' && $_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); $action=$_POST['action']??''; $id=(int)($_POST['id']??0); if($action==='delete'){ $pdo->prepare('DELETE FROM classes WHERE id=?')->execute([$id]); redirect('classes.php','Class deleted.'); } $code=trim($_POST['class_code']??'');$name=trim($_POST['class_name']??'');$teacher=(int)($_POST['teacher_id']??0);if(!$code||!$name||!$teacher)$error='Complete all class fields.';else try{if($action==='update')$pdo->prepare('UPDATE classes SET class_code=?,class_name=?,teacher_id=? WHERE id=?')->execute([$code,$name,$teacher,$id]);else $pdo->prepare('INSERT INTO classes(class_code,class_name,teacher_id) VALUES(?,?,?)')->execute([$code,$name,$teacher]);redirect('classes.php','Class saved.');}catch(PDOException $e){$error='Class code already exists.';}}
if ($me['role']==='admin' && isset($_POST['enroll'])) { check_csrf(); try{$pdo->prepare('INSERT INTO enrollments(class_id,student_id) VALUES(?,?)')->execute([(int)$_POST['class_id'],(int)$_POST['student_id']]);redirect('classes.php','Student enrolled.');}catch(PDOException $e){$error='Student is already enrolled.';} }
$edit=null;if($me['role']==='admin'&&isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM classes WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$teachers=$pdo->query("SELECT id,full_name FROM users WHERE role='teacher' AND is_active=1 ORDER BY full_name")->fetchAll();$students=$pdo->query("SELECT id,full_name FROM users WHERE role='student' AND is_active=1 ORDER BY full_name")->fetchAll();$sql='SELECT c.*,u.full_name teacher_name,COUNT(e.student_id) student_count FROM classes c JOIN users u ON u.id=c.teacher_id LEFT JOIN enrollments e ON e.class_id=c.id';$params=[];if($me['role']==='teacher'){$sql.=' WHERE c.teacher_id=?';$params[]=$me['id'];}$sql.=' GROUP BY c.id ORDER BY c.class_code';$q=$pdo->prepare($sql);$q->execute($params);$classes=$q->fetchAll();page_start($me['role']==='admin'?'Manage Classes':'My Classes',$me); ?>
<?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><div class="content-grid"><?php if($me['role']==='admin'):?><section class="panel"><div class="panel-heading"><div><h2><?=$edit?'Edit class':'Add class'?></h2><p>Assign a teacher to each class.</p></div></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=$edit['id']?>"><?php endif;?><div class="form-group"><label>Class code</label><input name="class_code" required value="<?=e($edit['class_code']??'')?>"></div><div class="form-group"><label>Class name</label><input name="class_name" required value="<?=e($edit['class_name']??'')?>"></div><div class="form-group"><label>Teacher</label><select name="teacher_id" required><?php foreach($teachers as $t):?><option value="<?=$t['id']?>" <?=($edit['teacher_id']??0)==$t['id']?'selected':''?>><?=e($t['full_name'])?></option><?php endforeach;?></select></div><button class="btn btn-primary">Save Class</button></form><hr style="margin:22px 0;border:.5px solid #e4e9ef"><h2>Enroll student</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="enroll" value="1"><div class="form-group"><label>Class</label><select name="class_id"><?php foreach($classes as $c):?><option value="<?=$c['id']?>"><?=e($c['class_code'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Student</label><select name="student_id"><?php foreach($students as $s):?><option value="<?=$s['id']?>"><?=e($s['full_name'])?></option><?php endforeach;?></select></div><button class="btn btn-secondary">Enroll</button></form></section><?php endif;?><section class="panel"><div class="panel-heading"><div><h2>Class list</h2><p><?=count($classes)?> class(es)</p></div></div><div class="table-wrap"><table><thead><tr><th>Code</th><th>Class</th><th>Teacher</th><th>Students</th><?php if($me['role']==='admin'):?><th>Actions</th><?php endif;?></tr></thead><tbody><?php foreach($classes as $c):?><tr><td><?=e($c['class_code'])?></td><td><?=e($c['class_name'])?></td><td><?=e($c['teacher_name'])?></td><td><?=$c['student_count']?></td><?php if($me['role']==='admin'):?><td><a class="table-btn" href="?edit=<?=$c['id']?>">Edit</a><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="table-btn" onclick="return confirm('Delete class?')">Delete</button></form></td><?php endif;?></tr><?php endforeach;?></tbody></table></div></section></div><?php page_end(); ?>
